const $=selector=>document.querySelector(selector);
const panels=['#login-panel','#change-panel','#account-panel'];
function show(panel){for(const selector of panels)$(selector).hidden=selector!==panel;}
function message(value){$('#status').textContent=value;}
async function api(method='GET',body){const response=await fetch('/api/platform-auth',{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Please try again.');return data;}
function renderAccount(user){$('#account-name').textContent=user.fullName;$('#account-email').textContent=user.email;$('#account-roles').innerHTML=user.roles.map(role=>{const scope=[role.campusCode,role.gradeCode,role.sectionCode].filter(Boolean).join(' · ');return `<span>${escapeHtml(role.displayName)}${scope?` — ${escapeHtml(scope)}`:''}</span>`;}).join('');show('#account-panel');}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;message('Signing in…');try{const data=await api('POST',{action:'login',email:form.elements.email.value.trim(),password:form.elements.password.value});form.reset();message('');if(data.mustChangePassword)show('#change-panel');else renderAccount(data.user);}catch(error){message(error.message);}finally{button.disabled=false;}});
$('#change-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');if(form.elements.newPassword.value!==form.elements.confirmPassword.value){message('The new passwords do not match.');return;}if(form.elements.newPassword.value===form.elements.currentPassword.value){message('Choose a password different from your temporary passcode.');return;}button.disabled=true;message('Saving your new password…');try{const data=await api('POST',{action:'changePassword',currentPassword:form.elements.currentPassword.value,newPassword:form.elements.newPassword.value});form.reset();message('');renderAccount(data.user);}catch(error){message(error.message);}finally{button.disabled=false;}});
$('#sign-out').addEventListener('click',async()=>{try{await api('DELETE');}catch{}show('#login-panel');message('You have signed out.');});
try{const data=await api();if(data.mustChangePassword)show('#change-panel');else renderAccount(data.user);}catch{show('#login-panel');}
